(7369815, 1155952, 120171, '<td valign="top">i really like this shot but the models eyes are looking too far to her right which is taking the overall connection away for me.</td>', 'i really like this shot but the models eyes are looking too far to her right which is taking the overall connection away for me.', '2015-06-22 18:24:34.000000', NULL, 1),
(7369817, 1155163, 120171, '<td valign="top">Pity the gulls wing is clipped.<br/> <br/>More detail in the male and less banding in the sky would have taken this image to the next level.</td>', 'Pity the gulls wing is clipped. More detail in the male and less banding in the sky would have taken this image to the next level.', '2015-06-22 18:26:43.000000', NULL, 1),
(7369862, 1155247, 30454, '<td valign="top">Excellent idea and well executed. Just to nit pick, those white hallows(lens flare) is taking away fron a great image.</td>', 'Excellent idea and well executed. Just to nit pick, those white hallows(lens flare) is taking away fron a great image.', '2015-06-22 19:34:08.000000', NULL, 1),
