(7369870, 1155585, 30454, '<td valign="top">Excellent focus, nice DOF. Wish lighting was little better.</td>', 'Excellent focus, nice DOF. Wish lighting was little better.', '2015-06-22 19:43:15.000000', NULL, 1),
