(7371051, 1155398, 138630, '<td valign="top">Beautiful bird portrait - the detail on the feathers is excellent and the light is lovely.</td>', 'Beautiful bird portrait - the detail on the feathers is excellent and the light is lovely.', '2015-06-24 00:03:42.000000', NULL, 1),
(7371053, 1155017, 138630, '<td valign="top">What a very beautiful and unusual bird and a great capture of it.  Love the smooth background that really sets him off.</td>', 'What a very beautiful and unusual bird and a great capture of it.  Love the smooth background that really sets him off.', '2015-06-24 00:04:42.000000', NULL, 1),
(7371054, 1155346, 138630, '<td valign="top">Lovely the way it catches the light and is caught in that fine, feathery plant.</td>', 'Lovely the way it catches the light and is caught in that fine, feathery plant.', '2015-06-24 00:05:14.000000', NULL, 1),
(7371055, 1155873, 138630, '<td valign="top">Very pretty bird - focus is a bit soft but I love the light.</td>', 'Very pretty bird - focus is a bit soft but I love the light.', '2015-06-24 00:05:41.000000', NULL, 1),
(7371056, 1155822, 138630, '<td valign="top">Nice idea - they go together in more than one way.  The background looks funny and blotchy, but the tones are great.</td>', 'Nice idea - they go together in more than one way.  The background looks funny and blotchy, but the tones are great.', '2015-06-24 00:06:21.000000', NULL, 1),
(7371077, 1155716, 138630, '<td valign="top">Excellent detail and color.  I might like a bit more space in front of him.  Is that a tongue?</td>', 'Excellent detail and color.  I might like a bit more space in front of him.  Is that a tongue?', '2015-06-24 00:26:51.000000', NULL, 1),
(7371079, 1155450, 138630, '<td valign="top">Gorgeous detail, light, color and I love the black reflection of the golden brown and white feather.</td>', 'Gorgeous detail, light, color and I love the black reflection of the golden brown and white feather.', '2015-06-24 00:27:31.000000', NULL, 1),
(7371081, 1155448, 138630, '<td valign="top">Nice idea for a set-up - a bit cluttered for me but I like the light and the rich textures and tones.</td>', 'Nice idea for a set-up - a bit cluttered for me but I like the light and the rich textures and tones.', '2015-06-24 00:28:47.000000', NULL, 1),
