(7371083, 1155517, 352, '<td valign="top">Now THERE''s the whimsy from a cat shot I was hoping for!!</td>', 'Now THERE''s the whimsy from a cat shot I was hoping for!!', '2015-06-24 00:30:38.000000', NULL, 1),
(7371085, 1155727, 138630, '<td valign="top">Just splendid and the black and white conversion was a must.  Someday I hope to see a white peacock.</td>', 'Just splendid and the black and white conversion was a must.  Someday I hope to see a white peacock.', '2015-06-24 00:31:17.000000', NULL, 1),
(7371086, 1155867, 138630, '<td valign="top">Cute idea.  The dof is a bit too shallow for me, but it does look as if you were both having fun.</td>', 'Cute idea.  The dof is a bit too shallow for me, but it does look as if you were both having fun.', '2015-06-24 00:32:33.000000', NULL, 1),
(7371087, 1155946, 138630, '<td valign="top">I saw a many legged creature immediately - good title.</td>', 'I saw a many legged creature immediately - good title.', '2015-06-24 00:33:00.000000', NULL, 1),
(7371089, 1154151, 138630, '<td valign="top">Tones are focus are just scrumptious.  I like the texture, too.  Lovely.</td>', 'Tones are focus are just scrumptious.  I like the texture, too.  Lovely.', '2015-06-24 00:33:34.000000', NULL, 1),
(7371091, 1155916, 138630, '<td valign="top">Nice portrait - could use a bit more detail and maybe the feet?  Lovely colors if a bit unnatural in my experience.</td>', 'Nice portrait - could use a bit more detail and maybe the feet?  Lovely colors if a bit unnatural in my experience.', '2015-06-24 00:34:42.000000', NULL, 1),
(7371175, 1155720, 62249, '<td valign="top">Kinda reminds me of some of my bad hair days :-). While I like the texture and the subtlety of the colors, overall the image lacks oomph.</td>', 'Kinda reminds me of some of my bad hair days :-). While I like the texture and the subtlety of the colors, overall the image lacks oomph.', '2015-06-24 01:24:32.000000', NULL, 1),
(7371179, 1155910, 62249, '<td valign="top">A different crop might strengthen this. I find myself paying too much attention to the bright green leaves near right edge of the frame.</td>', 'A different crop might strengthen this. I find myself paying too much attention to the bright green leaves near right edge of the frame.', '2015-06-24 01:25:46.000000', NULL, 1),
(7371186, 1155688, 62249, '<td valign="top">The ratio of grass to your subject is pretty high... A tighter crop would help.</td>', 'The ratio of grass to your subject is pretty high... A tighter crop would help.', '2015-06-24 01:26:58.000000', NULL, 1),
(7371188, 1155568, 62249, '<td valign="top">Fabulous title.</td>', 'Fabulous title.', '2015-06-24 01:27:28.000000', NULL, 1),
(7371196, 1154990, 62249, '<td valign="top">There''s a distracting bit of shiny stuff in her hair on the left (earring?), but other than that this is a nice take on the challenge. Perhaps a bit more light on the dark side of her face.</td>', 'There''s a distracting bit of shiny stuff in her hair on the left (earring?), but other than that this is a nice take on the challenge. Perhaps a bit more light on the dark side of her face.', '2015-06-24 01:29:27.000000', NULL, 1),
(7371202, 1155970, 62249, '<td valign="top">I like the effect you''re going for here. Wish the few white areas had been cloned out.</td>', 'I like the effect you''re going for here. Wish the few white areas had been cloned out.', '2015-06-24 01:31:12.000000', NULL, 1),
(7371205, 1155694, 62249, '<td valign="top">The lighting on the central feathers is beautiful.</td>', 'The lighting on the central feathers is beautiful.', '2015-06-24 01:33:03.000000', NULL, 1),
(7371210, 1155927, 62249, '<td valign="top">Gross, but funny.</td>', 'Gross, but funny.', '2015-06-24 01:34:06.000000', NULL, 1),
(7371216, 1155558, 62249, '<td valign="top">Clever. Well lit and nicely processed.</td>', 'Clever. Well lit and nicely processed.', '2015-06-24 01:35:28.000000', NULL, 1),
(7371219, 1155691, 62249, '<td valign="top">Lighting is rather flat and uninteresting. Also consider cloning out extraneous dust &amp; specks.</td>', 'Lighting is rather flat and uninteresting. Also consider cloning out extraneous dust & specks.', '2015-06-24 01:37:38.000000', NULL, 1),
