(7371223, 1155867, 62249, '<td valign="top">A featherstache. Cute.would like just a tiny bit more DOF so that her far eye was a little sharper.</td>', 'A featherstache. Cute.would like just a tiny bit more DOF so that her far eye was a little sharper.', '2015-06-24 01:40:23.000000', NULL, 1),
(7371224, 1155648, 62249, '<td valign="top">Need to do a bit more touch up on spots. Several unsightly splotches in the upper half of the image.</td>', 'Need to do a bit more touch up on spots. Several unsightly splotches in the upper half of the image.', '2015-06-24 01:41:36.000000', NULL, 1),
(7371232, 1155900, 62249, '<td valign="top">Lots of dust spots on the feathers that could''ve been cloned out. And what is the strange dark scribbly rectangle behind the top of the left feather?</td>', 'Lots of dust spots on the feathers that could''ve been cloned out. And what is the strange dark scribbly rectangle behind the top of the left feather?', '2015-06-24 01:47:14.000000', NULL, 1),
(7371234, 1155573, 62249, '<td valign="top">Subtle. A bit too much so. Too much support struts, not enough bird. But I like the concept a lot.</td>', 'Subtle. A bit too much so. Too much support struts, not enough bird. But I like the concept a lot.', '2015-06-24 01:48:42.000000', NULL, 1),
(7371243, 1155327, 62249, '<td valign="top">The white paper is WAY too distracting from the feather &amp; inkwell. Maybe have the inkwell on the paper, along with a bit of writing, and crop much tighter to show only a portion of the page?</td>', 'The white paper is WAY too distracting from the feather & inkwell. Maybe have the inkwell on the paper, along with a bit of writing, and crop much tighter to show only a portion of the page?', '2015-06-24 01:50:26.000000', NULL, 1),
(7371248, 1155327, 352, '<td valign="top">Lack of focus on this one bothers me.</td>', 'Lack of focus on this one bothers me.', '2015-06-24 01:52:02.000000', NULL, 1),
(7371249, 1154902, 62249, '<td valign="top">The swoosh effect is cool. Lighting on the face of the feather is too flat.</td>', 'The swoosh effect is cool. Lighting on the face of the feather is too flat.', '2015-06-24 01:52:05.000000', NULL, 1),
(7371252, 1155725, 62249, '<td valign="top">Interesting elements. Composition doesn''t quite work. Needs to be rearranged in a way that leads a viewer''s eye through the scene.</td>', 'Interesting elements. Composition doesn''t quite work. Needs to be rearranged in a way that leads a viewer''s eye through the scene.', '2015-06-24 01:53:17.000000', NULL, 1),
(7371258, 1155917, 352, '<td valign="top">DNMC - no feather here...</td>', 'DNMC - no feather here...', '2015-06-24 01:56:11.000000', NULL, 1),
(7371259, 1154087, 62249, '<td valign="top">Angling for a brown ribbon? The right half of the image actually works very well as an abstract.</td>', 'Angling for a brown ribbon? The right half of the image actually works very well as an abstract.', '2015-06-24 01:57:09.000000', NULL, 1),
(7371282, 1155441, 62249, '<td valign="top">Heh, I''ve taken hundreds of photos of my chickens and always have a hard time getting their eyes in sharp focus because they move around so quickly. You solved the problem brilliantly by focusing on the, er, business end of the hen.</td>', 'Heh, I''ve taken hundreds of photos of my chickens and always have a hard time getting their eyes in sharp focus because they move around so quickly. You solved the problem brilliantly by focusing on the, er, business end of the hen.', '2015-06-24 02:09:28.000000', NULL, 1),
(7371286, 1155817, 62249, '<td valign="top">The light speck on the "eye" of the foreground feather should''ve been cloned out. I like your use of lighting on that feather and the OOF background feathers work well too.</td>', 'The light speck on the "eye" of the foreground feather should''ve been cloned out. I like your use of lighting on that feather and the OOF background feathers work well too.', '2015-06-24 02:10:51.000000', NULL, 1),
(7371292, 1155885, 62249, '<td valign="top">I find this one oddly appealing. Wish you''d done more spot touch-up to get rid of light specks in the background, but otherwise the processing really works for this image.</td>', 'I find this one oddly appealing. Wish you''d done more spot touch-up to get rid of light specks in the background, but otherwise the processing really works for this image.', '2015-06-24 02:16:47.000000', NULL, 1),
