INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7372382, 1155005, 3306, '<td valign="top">Very funny and cute!</td>', 'Very funny and cute!', '2015-06-25 07:28:16.000000', NULL, 1),
(7372385, 1154882, 3306, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2015-06-25 07:30:15.000000', NULL, 1),
(7372386, 1155542, 3306, '<td valign="top">This would have done very well in the pastel challenge. Very nice.</td>', 'This would have done very well in the pastel challenge. Very nice.', '2015-06-25 07:32:48.000000', NULL, 1),
(7372387, 1155871, 3306, '<td valign="top">Nice composition</td>', 'Nice composition', '2015-06-25 07:34:04.000000', NULL, 1),
(7372388, 1155398, 3306, '<td valign="top">Spot on focus. Great capture</td>', 'Spot on focus. Great capture', '2015-06-25 07:37:23.000000', NULL, 1),
(7372390, 1155893, 180696, '<td valign="top">Great idea, but I just think that the image is too soft and not quite visible enough. I always say to people... Imagine your photo being printed on a canvas and hanging it on your wall. Will this one work? It may be lost in the print</td>', 'Great idea, but I just think that the image is too soft and not quite visible enough. I always say to people... Imagine your photo being printed on a canvas and hanging it on your wall. Will this one work? It may be lost in the print', '2015-06-25 07:46:27.000000', NULL, 1),
(7372392, 1155763, 180696, '<td valign="top">Lovely idea, I would have liked to see a little more shadows, it often provides a little more depth, I feel that the feather seems a little flat. Some shadowing here might have got rid of that. The feather also seems just a tad too set-up and lying in a natural position. Otherwise a very good idea!</td>', 'Lovely idea, I would have liked to see a little more shadows, it often provides a little more depth, I feel that the feather seems a little flat. Some shadowing here might have got rid of that. The feather also seems just a tad too set-up and lying in a natural position. Otherwise a very good idea!', '2015-06-25 07:49:48.000000', NULL, 1),
(7372393, 1155843, 180696, '<td valign="top">I like it. Nice pin sharp eye and great detail on the feathers. DOF is good</td>', 'I like it. Nice pin sharp eye and great detail on the feathers. DOF is good', '2015-06-25 07:50:36.000000', NULL, 1),
(7372395, 1155928, 180696, '<td valign="top">I like the feathers that are nice and "clean". I am not quite sure though about the blown-out whites. It would have been nice to see the introduced colour to flow more throughout the background</td>', 'I like the feathers that are nice and "clean". I am not quite sure though about the blown-out whites. It would have been nice to see the introduced colour to flow more throughout the background', '2015-06-25 07:54:14.000000', NULL, 1),
(7372396, 1155441, 180696, '<td valign="top">Yes, its a chicken... No artistic value and the rule of thirds hasn''t been applied either. The image is dead centre. Also too much clutter behind the subject matter which draws one''s eye away from the subject.</td>', 'Yes, its a chicken... No artistic value and the rule of thirds hasn''t been applied either. The image is dead centre. Also too much clutter behind the subject matter which draws one''s eye away from the subject.', '2015-06-25 07:57:44.000000', NULL, 1),
(7372397, 1155532, 180696, '<td valign="top">Lovely image and colours! I just feel that the image as a whole is cropped far too tightly though. The blurred spot around the beak could surely have been cloned out.</td>', 'Lovely image and colours! I just feel that the image as a whole is cropped far too tightly though. The blurred spot around the beak could surely have been cloned out.', '2015-06-25 07:59:19.000000', NULL, 1),
(7372398, 1155956, 180696, '<td valign="top">One line... I struggle to see the bird lost in the image</td>', 'One line... I struggle to see the bird lost in the image', '2015-06-25 07:59:55.000000', NULL, 1),
(7372399, 1155346, 180696, '<td valign="top">Nice lines, composition and sharpness on the feather. Nice sharp image and you got the theme just right :)</td>', 'Nice lines, composition and sharpness on the feather. Nice sharp image and you got the theme just right :)', '2015-06-25 08:00:48.000000', NULL, 1),
(7372400, 1154830, 180696, '<td valign="top">Lovely lines, just one bit of critique though, I would''ve like to see the end of the feather and not have it cropped so tightly. Love the idea!</td>', 'Lovely lines, just one bit of critique though, I would''ve like to see the end of the feather and not have it cropped so tightly. Love the idea!', '2015-06-25 08:02:29.000000', NULL, 1),
(7372403, 1154973, 180696, '<td valign="top">Idea, image as a whole and colours are great. The only thing while taking photos of animals or people though, is that one should try to keep the eyes, face, mouth or beak in this case, pin-sharp and in focus. Yes the feathers adhere to the theme, it''s just that due to the fact that the beak is part of the image, it could''ve been sharper.</td>', 'Idea, image as a whole and colours are great. The only thing while taking photos of animals or people though, is that one should try to keep the eyes, face, mouth or beak in this case, pin-sharp and in focus. Yes the feathers adhere to the theme, it''s just that due to the fact that the beak is part of the image, it could''ve been sharper.', '2015-06-25 08:06:28.000000', NULL, 1),
(7372404, 1155822, 180696, '<td valign="top">A lovely image indeed. Love the softness created</td>', 'A lovely image indeed. Love the softness created', '2015-06-25 08:07:38.000000', NULL, 1),
(7372405, 1155765, 180696, '<td valign="top">Sorry, but this entire image is totally out of focus and thus will not get a great vote from me...</td>', 'Sorry, but this entire image is totally out of focus and thus will not get a great vote from me...', '2015-06-25 08:08:34.000000', NULL, 1),
(7372409, 1155894, 180696, '<td valign="top">Nice image and like the clarity. one thing I have an issue with though, is the fact that the better use of the rule of thirds applied, would''ve added more value to the image.</td>', 'Nice image and like the clarity. one thing I have an issue with though, is the fact that the better use of the rule of thirds applied, would''ve added more value to the image.', '2015-06-25 08:17:09.000000', NULL, 1),
(7372411, 1155867, 180696, '<td valign="top">An important rule in photography... Eyes should always be pin-sharp!</td>', 'An important rule in photography... Eyes should always be pin-sharp!', '2015-06-25 08:18:11.000000', NULL, 1),
(7372414, 1155773, 180696, '<td valign="top">Composition is good, Good DOF. Nice display of feathers :)</td>', 'Composition is good, Good DOF. Nice display of feathers :)', '2015-06-25 08:18:45.000000', NULL, 1),
(7372415, 1154865, 180696, '<td valign="top">Sorry, but I don''t feel that the graininess lends to the value of the image. Good composition though</td>', 'Sorry, but I don''t feel that the graininess lends to the value of the image. Good composition though', '2015-06-25 08:19:39.000000', NULL, 1),
(7372417, 1155783, 180696, '<td valign="top">I always say... Try to imagine a photo of yours printed on a canvas and hanging in a gallery or on your wall at home... Will it work or not?</td>', 'I always say... Try to imagine a photo of yours printed on a canvas and hanging in a gallery or on your wall at home... Will it work or not?', '2015-06-25 08:20:57.000000', NULL, 1),
(7372419, 1155463, 180696, '<td valign="top">Good composition and lovely idea, a little more sharpness on the droplet would''ve added even more dramatic effect here</td>', 'Good composition and lovely idea, a little more sharpness on the droplet would''ve added even more dramatic effect here', '2015-06-25 08:21:55.000000', NULL, 1),
(7372421, 1155781, 180696, '<td valign="top">Yes, birds with feathers and one can understand the interpretation of the theme "Feathers" here, but I feel that the subject matter is too distant and all the extra space around the subject matter doesn''t lend any extra value to the photo</td>', 'Yes, birds with feathers and one can understand the interpretation of the theme "Feathers" here, but I feel that the subject matter is too distant and all the extra space around the subject matter doesn''t lend any extra value to the photo', '2015-06-25 08:24:04.000000', NULL, 1),
(7372422, 1154689, 180696, '<td valign="top">The theme is well depicted. I love the colours. Nice flow of lines made by the composition of the feathers</td>', 'The theme is well depicted. I love the colours. Nice flow of lines made by the composition of the feathers', '2015-06-25 08:25:09.000000', NULL, 1),
(7372424, 1155612, 180696, '<td valign="top">Good depiction of the theme. Good contrast and softness and most importantly, good pin-sharp eyes, an important rule in photography!</td>', 'Good depiction of the theme. Good contrast and softness and most importantly, good pin-sharp eyes, an important rule in photography!', '2015-06-25 08:27:12.000000', NULL, 1),
(7372426, 1155935, 180696, '<td valign="top">Sorry, a bird on a stick with another stick in the image that lends absolutely no value to the theme or image as a whole. A very flat and uninteresting image</td>', 'Sorry, a bird on a stick with another stick in the image that lends absolutely no value to the theme or image as a whole. A very flat and uninteresting image', '2015-06-25 08:28:42.000000', NULL, 1),
(7372428, 1155916, 180696, '<td valign="top">Like the pin-sharp eyes and like the soft effect of the feathers. Good DOF</td>', 'Like the pin-sharp eyes and like the soft effect of the feathers. Good DOF', '2015-06-25 08:29:48.000000', NULL, 1),
(7372429, 1154617, 180696, '<td valign="top">The theme is there, but far, far away... The image has too much negative space. Could''ve been cropped a lot tighter and still have a good image.</td>', 'The theme is there, but far, far away... The image has too much negative space. Could''ve been cropped a lot tighter and still have a good image.', '2015-06-25 08:31:09.000000', NULL, 1),
(7372430, 1155247, 180696, '<td valign="top">One gets the overall impression of what was implied, but it would''ve been nice to have seen a real quail that is usually used for script and not an ordinary feather. Still a great image and good composition</td>', 'One gets the overall impression of what was implied, but it would''ve been nice to have seen a real quail that is usually used for script and not an ordinary feather. Still a great image and good composition', '2015-06-25 08:34:07.000000', NULL, 1),
(7372431, 1155691, 180696, '<td valign="top">Nice colourful image, personally would have like to see the feathers more at an angle and not so staged. Nice and sharp</td>', 'Nice colourful image, personally would have like to see the feathers more at an angle and not so staged. Nice and sharp', '2015-06-25 08:35:39.000000', NULL, 1),
(7372432, 1155791, 180696, '<td valign="top">Good composition and very sharp! Great use of DOF</td>', 'Good composition and very sharp! Great use of DOF', '2015-06-25 08:36:14.000000', NULL, 1),
(7372433, 1154726, 180696, '<td valign="top">Good pin-sharp image and tells a good story. The theme is spot on :)</td>', 'Good pin-sharp image and tells a good story. The theme is spot on :)', '2015-06-25 08:37:29.000000', NULL, 1),
(7372434, 1155311, 180696, '<td valign="top">thinking out of the box is greatly supported by me personally! A good, sharp and interesting image, well done! :)</td>', 'thinking out of the box is greatly supported by me personally! A good, sharp and interesting image, well done! :)', '2015-06-25 08:38:49.000000', NULL, 1),
(7372435, 1155573, 180696, '<td valign="top">This was an accident, right???</td>', 'This was an accident, right???', '2015-06-25 08:39:19.000000', NULL, 1),
(7372438, 1155469, 180696, '<td valign="top">Always love photos of guinea fowl and their interesting feathers. A good image. Just a pity that the face is cropped a little tight</td>', 'Always love photos of guinea fowl and their interesting feathers. A good image. Just a pity that the face is cropped a little tight', '2015-06-25 08:52:05.000000', NULL, 1),
(7372439, 1155353, 180696, '<td valign="top">A nice pin-sharp image and vibrant colours of feathers</td>', 'A nice pin-sharp image and vibrant colours of feathers', '2015-06-25 08:52:38.000000', NULL, 1),
(7372440, 1155871, 180696, '<td valign="top">Brilliant leading, flowing feel. I love everything about it! :)</td>', 'Brilliant leading, flowing feel. I love everything about it! :)', '2015-06-25 08:53:22.000000', NULL, 1),
(7372441, 1155450, 180696, '<td valign="top">Good photo, would''ve preferred to see a slightly tighter crop and also not having the subject matter centred in the image. Applying the rule of thirds here would''ve added more value</td>', 'Good photo, would''ve preferred to see a slightly tighter crop and also not having the subject matter centred in the image. Applying the rule of thirds here would''ve added more value', '2015-06-25 08:55:32.000000', NULL, 1),
(7372442, 1154703, 180696, '<td valign="top">Feathers alright! :)</td>', 'Feathers alright! :)', '2015-06-25 08:56:04.000000', NULL, 1),
(7372444, 1155446, 180696, '<td valign="top">Sorry, but not sharp enough and the composition could have been improved. The stone on the bottom left could have been left without</td>', 'Sorry, but not sharp enough and the composition could have been improved. The stone on the bottom left could have been left without', '2015-06-25 08:57:20.000000', NULL, 1),
(7372447, 1155879, 180696, '<td valign="top">A family photo for the album...</td>', 'A family photo for the album...', '2015-06-25 08:58:05.000000', NULL, 1),
(7372449, 1155678, 180696, '<td valign="top">Personally I feel that all the left-over space on the right could have been taken care of. The image is too strict for me and isn''t very pleasing. If it were more at an angle it would definitely have contributed to a much better over-all image with more character</td>', 'Personally I feel that all the left-over space on the right could have been taken care of. The image is too strict for me and isn''t very pleasing. If it were more at an angle it would definitely have contributed to a much better over-all image with more character', '2015-06-25 09:00:06.000000', NULL, 1),
(7372450, 1154735, 180696, '<td valign="top">Brilliant!</td>', 'Brilliant!', '2015-06-25 09:00:34.000000', NULL, 1),
(7372451, 1155817, 180696, '<td valign="top">Good DOF and great composition</td>', 'Good DOF and great composition', '2015-06-25 09:00:55.000000', NULL, 1),
(7372453, 1155840, 180696, '<td valign="top">Good, sharp image with good composition and nice soft colours</td>', 'Good, sharp image with good composition and nice soft colours', '2015-06-25 09:01:38.000000', NULL, 1),
(7372454, 1155804, 180696, '<td valign="top">A family photo for the album...</td>', 'A family photo for the album...', '2015-06-25 09:02:00.000000', NULL, 1),
