(7374089, 1155163, 61396, '<td valign="top">a classic <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=75618" rel="nofollow" target="_blank">odriew</a> subject matter and composition</td>', 'a classic  odriew subject matter and composition', '2015-06-27 11:26:43.000000', NULL, 1),
(7374102, 1155200, 65234, '<td valign="top">Aw, a baby bird in the making.  Very nice juxtaposition with the feathers.  Based on the size of the feathers I suspect that egg came from a smaller bird, but I still like the idea and the execution.</td>', 'Aw, a baby bird in the making.  Very nice juxtaposition with the feathers.  Based on the size of the feathers I suspect that egg came from a smaller bird, but I still like the idea and the execution.', '2015-06-27 11:42:21.000000', NULL, 1),
(7374103, 1155694, 65234, '<td valign="top">Not sure that was a kiss from what I''ve seen of flamingo interactions and the way the foreground bird is poufed, but those feathers make a nice pattern.  I might have tried cropping closer to emphasize them even more.</td>', 'Not sure that was a kiss from what I''ve seen of flamingo interactions and the way the foreground bird is poufed, but those feathers make a nice pattern.  I might have tried cropping closer to emphasize them even more.', '2015-06-27 11:43:44.000000', NULL, 1),
(7374105, 1155909, 65234, '<td valign="top">Looks lonely to me. I like the subtle colors and patterns in the water.</td>', 'Looks lonely to me. I like the subtle colors and patterns in the water.', '2015-06-27 11:44:55.000000', NULL, 1),
(7374108, 1155951, 65234, '<td valign="top">Striking image.  For this challenge I kind of expect the emphasis to be on the feathers, though, and they''re less detailed than the water drops.</td>', 'Striking image.  For this challenge I kind of expect the emphasis to be on the feathers, though, and they''re less detailed than the water drops.', '2015-06-27 11:46:46.000000', NULL, 1),
(7374111, 1155883, 113411, '<td valign="top">How fabulous !!!</td>', 'How fabulous !!!', '2015-06-27 11:47:42.000000', NULL, 1),
(7374112, 1155897, 113411, '<td valign="top">I love this!!!</td>', 'I love this!!!', '2015-06-27 11:48:02.000000', NULL, 1),
(7374113, 1155843, 65234, '<td valign="top">Aww, what a cutie.  I like the poufy feathers.  Hope that was a happy pouf and not a come-one-step-closer-and-I''ll-bite-you pouf!</td>', 'Aww, what a cutie.  I like the poufy feathers.  Hope that was a happy pouf and not a come-one-step-closer-and-I''ll-bite-you pouf!', '2015-06-27 11:48:09.000000', NULL, 1),
