(7374129, 1154882, 65234, '<td valign="top">Love the backlighting and the stop-action is crystal clear.  Doesn''t look like enough food for 2 big chicks!</td>', 'Love the backlighting and the stop-action is crystal clear.  Doesn''t look like enough food for 2 big chicks!', '2015-06-27 12:00:51.000000', NULL, 1),
(7374131, 1155791, 65234, '<td valign="top">Beautiful bird!  I like the soft vignetting.</td>', 'Beautiful bird!  I like the soft vignetting.', '2015-06-27 12:01:32.000000', NULL, 1),
