(7374136, 1155517, 65234, '<td valign="top">Bad kitty!!  LOVE that you got her licking her lips.  And the feathers tell the story.  Well done.</td>', 'Bad kitty!!  LOVE that you got her licking her lips.  And the feathers tell the story.  Well done.', '2015-06-27 12:03:24.000000', NULL, 1),
(7374140, 1155871, 65234, '<td valign="top">Much more interesting than a single feather.  The crossing makes for fun patterns.</td>', 'Much more interesting than a single feather.  The crossing makes for fun patterns.', '2015-06-27 12:06:22.000000', NULL, 1),
