(7374641, 1154882, 97225, '<td valign="top">Fabulous capture. Beautiful detail and dof. Stop action is superb. 9 (Top 3).</td>', 'Fabulous capture. Beautiful detail and dof. Stop action is superb. 9 (Top 3).', '2015-06-28 02:51:51.000000', NULL, 1),
(7374642, 1154151, 97225, '<td valign="top">Beautifully delicate.</td>', 'Beautifully delicate.', '2015-06-28 02:52:09.000000', NULL, 1),
