(7374714, 1155492, 156466, '<td valign="top">Didn''t something like this get you in trouble in a black and white challenge last year?</td>', 'Didn''t something like this get you in trouble in a black and white challenge last year?', '2015-06-28 09:16:40.000000', NULL, 1),
(7374726, 1155956, 156466, '<td valign="top">Great street capture, but the bird gets lost.</td>', 'Great street capture, but the bird gets lost.', '2015-06-28 10:13:56.000000', NULL, 1),
(7374730, 1155163, 30364, '<td valign="top">Mr Google says this name is some bloke from a TV show I''ve never seen.  So I''m out of my depth with that, but not with this photograph which is easily the most interesting in the challenge.  Composition is really sublime.  Lighting, especially on the bloke, is great.  A terrific photograph made all the more admirable by appearing in a challenge characterised by banality and predictability.  I hang about your neck the albatross of an Order of the Thumb.  10 and thank you.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=800078" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg"/></a></td>', 'Mr Google says this name is some bloke from a TV show I''ve never seen.  So I''m out of my depth with that, but not with this photograph which is easily the most interesting in the challenge.  Composition is really sublime.  Lighting, especially on the bloke, is great.  A terrific photograph made all the more admirable by appearing in a challenge characterised by banality and predictability.  I hang about your neck the albatross of an Order of the Thumb.  10 and thank you.', '2015-06-28 10:31:32.000000', NULL, 1),
(7374735, 1155469, 50864, '<td valign="top">Lovely processing for these beautiful feathers.</td>', 'Lovely processing for these beautiful feathers.', '2015-06-28 10:44:32.000000', NULL, 1),
(7374776, 1155039, 180696, '<td valign="top">Your image seems a little out of focus and a little noisy. Usually when photographing animals or humans, the eye is expected to be pin sharp. It''s just what is expected.</td>', 'Your image seems a little out of focus and a little noisy. Usually when photographing animals or humans, the eye is expected to be pin sharp. It''s just what is expected.', '2015-06-28 11:55:00.000000', NULL, 1),
(7374777, 1155909, 180696, '<td valign="top">The feather just seems lost in all the space around it</td>', 'The feather just seems lost in all the space around it', '2015-06-28 11:55:38.000000', NULL, 1),
(7374778, 1155367, 180696, '<td valign="top">A nice photo, I would''ve preferred a little vibrancy on the face as it is as a matter of a fact, part of the total image. I like the rule of thirds applied though</td>', 'A nice photo, I would''ve preferred a little vibrancy on the face as it is as a matter of a fact, part of the total image. I like the rule of thirds applied though', '2015-06-28 11:57:35.000000', NULL, 1),
(7374781, 1155925, 180696, '<td valign="top">A lovely crisp image, I would''ve liked to see a soft colour background, the black is a little too much</td>', 'A lovely crisp image, I would''ve liked to see a soft colour background, the black is a little too much', '2015-06-28 11:58:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7374783, 1154835, 180696, '<td valign="top">Sorry, but I feel that the white background doesn''t do your image the justice it deserves</td>', 'Sorry, but I feel that the white background doesn''t do your image the justice it deserves', '2015-06-28 11:59:57.000000', NULL, 1),
(7374784, 1155168, 180696, '<td valign="top">I love your image, The theme well thought out</td>', 'I love your image, The theme well thought out', '2015-06-28 12:00:21.000000', NULL, 1),
(7374785, 1155771, 180696, '<td valign="top">Good image indeed, just not sure about the halo effect around the subject matter. I like that you thought out of the box and presented something good!</td>', 'Good image indeed, just not sure about the halo effect around the subject matter. I like that you thought out of the box and presented something good!', '2015-06-28 12:01:37.000000', NULL, 1),
(7374786, 1155398, 180696, '<td valign="top">Very lovely crisp image in total. Perfect DOF and the white balance is spot on!</td>', 'Very lovely crisp image in total. Perfect DOF and the white balance is spot on!', '2015-06-28 12:02:50.000000', NULL, 1),
(7374787, 1155835, 180696, '<td valign="top">I like your photo, the cropping is a little tight though</td>', 'I like your photo, the cropping is a little tight though', '2015-06-28 12:03:38.000000', NULL, 1),
(7374788, 1155179, 180696, '<td valign="top">I''m not sure whether this is depicting the theme quite as it was intended</td>', 'I''m not sure whether this is depicting the theme quite as it was intended', '2015-06-28 12:04:27.000000', NULL, 1),
(7374789, 1154994, 180696, '<td valign="top">Sorry, but I can''t even tell what is going on here??</td>', 'Sorry, but I can''t even tell what is going on here??', '2015-06-28 12:05:00.000000', NULL, 1),
(7374793, 1154684, 180696, '<td valign="top">Good attempt at this theme, but your image appears to be noisy and not sharp enough. One would expect that at least the upper feather be pin sharp. It is a harsh on the eyes when there is no sharpness</td>', 'Good attempt at this theme, but your image appears to be noisy and not sharp enough. One would expect that at least the upper feather be pin sharp. It is a harsh on the eyes when there is no sharpness', '2015-06-28 12:06:55.000000', NULL, 1),
(7374794, 1155952, 180696, '<td valign="top">Very professional take on this</td>', 'Very professional take on this', '2015-06-28 12:07:20.000000', NULL, 1),
(7374797, 1155803, 180696, '<td valign="top">The detail was lost here and one would expect to see a little more sharpness of especially the feathers as it is the theme. Besides that, usually when taking photos of anything, if the eyes are in the picture, it should always be sharp, this is what the pros say?</td>', 'The detail was lost here and one would expect to see a little more sharpness of especially the feathers as it is the theme. Besides that, usually when taking photos of anything, if the eyes are in the picture, it should always be sharp, this is what the pros say?', '2015-06-28 12:12:41.000000', NULL, 1),
(7374798, 1155401, 180696, '<td valign="top">Great photo. Love the composition and everything that goes with it!</td>', 'Great photo. Love the composition and everything that goes with it!', '2015-06-28 12:13:16.000000', NULL, 1),
(7374799, 1155417, 180696, '<td valign="top">I am speechless...</td>', 'I am speechless...', '2015-06-28 12:13:47.000000', NULL, 1),
(7374800, 1155634, 180696, '<td valign="top">I find that the feather is very lost and no detail anywhere...</td>', 'I find that the feather is very lost and no detail anywhere...', '2015-06-28 12:16:09.000000', NULL, 1),
(7374801, 1154969, 180696, '<td valign="top">Nice detail, good composition, white balance seems good</td>', 'Nice detail, good composition, white balance seems good', '2015-06-28 12:16:50.000000', NULL, 1),
(7374802, 1155458, 180696, '<td valign="top">Interesting. Like the blue hue very much</td>', 'Interesting. Like the blue hue very much', '2015-06-28 12:17:22.000000', NULL, 1),
(7374806, 1155328, 180696, '<td valign="top">The idea is there in terms of the theme, but I find that the subject matter is just too tightly cropped at the top and having the embankment just finding it''s way into the frame doesn''t do the image any justice</td>', 'The idea is there in terms of the theme, but I find that the subject matter is just too tightly cropped at the top and having the embankment just finding it''s way into the frame doesn''t do the image any justice', '2015-06-28 12:19:14.000000', NULL, 1),
(7374813, 1155529, 180696, '<td valign="top">Sorry to say, but this image is way too over-processed, one can easily tell by just looking at the front of the neck of the bird. It is also not sharp and all the colours are wrong - way over-worked! It seems that you tried to rectify for the lack of depth of field, rather try to do it in camera as to after the shot is taken. Look at your settings, aperture and F-stop more carefully next time. You threw away a good opportunity here as these Blue Cranes are some of the most colourful birds and have fascinating detail on their feathers.</td>', 'Sorry to say, but this image is way too over-processed, one can easily tell by just looking at the front of the neck of the bird. It is also not sharp and all the colours are wrong - way over-worked! It seems that you tried to rectify for the lack of depth of field, rather try to do it in camera as to after the shot is taken. Look at your settings, aperture and F-stop more carefully next time. You threw away a good opportunity here as these Blue Cranes are some of the most colourful birds and have fascinating detail on their feathers.', '2015-06-28 12:23:52.000000', NULL, 1),
(7374816, 1155568, 180696, '<td valign="top">It''s an absolutely great photo, Just one bit of critique though and that''s the composition. The rule of thirds is always important and always captures the moment more dramatically</td>', 'It''s an absolutely great photo, Just one bit of critique though and that''s the composition. The rule of thirds is always important and always captures the moment more dramatically', '2015-06-28 12:27:20.000000', NULL, 1),
(7374819, 1155533, 180696, '<td valign="top">The stark white just hit he right in the eyes... The background could jave been softened with a shade of sorts...</td>', 'The stark white just hit he right in the eyes... The background could jave been softened with a shade of sorts...', '2015-06-28 12:28:20.000000', NULL, 1),
(7374821, 1155321, 180696, '<td valign="top">A nice pastel arrangement. Nice colours, would like to see at least some portion of the image a little in focus though...</td>', 'A nice pastel arrangement. Nice colours, would like to see at least some portion of the image a little in focus though...', '2015-06-28 12:29:37.000000', NULL, 1),
(7374822, 1155912, 180696, '<td valign="top">Nice clean image with a nice hue to it and I like the leading lines you''ve captured. Well done</td>', 'Nice clean image with a nice hue to it and I like the leading lines you''ve captured. Well done', '2015-06-28 12:30:28.000000', NULL, 1),
(7374823, 1155953, 180696, '<td valign="top">Unfortunately the purists will find the grass very distracting, especially the two blades of grass on the right. This could have been omitted in this challenge</td>', 'Unfortunately the purists will find the grass very distracting, especially the two blades of grass on the right. This could have been omitted in this challenge', '2015-06-28 12:32:06.000000', NULL, 1),
(7374825, 1155694, 180696, '<td valign="top">It''s nice to see these majestic birds and yes, you focused on the feathers, But your composition and cropping thereof could''ve been better. Always keep the rule of thirds in mind, there is a reason for it, it creates an emotion and makes a statement</td>', 'It''s nice to see these majestic birds and yes, you focused on the feathers, But your composition and cropping thereof could''ve been better. Always keep the rule of thirds in mind, there is a reason for it, it creates an emotion and makes a statement', '2015-06-28 12:34:41.000000', NULL, 1),
(7374826, 1155905, 180696, '<td valign="top">The grass is definitely very distracting and not to mention that the image in it''s totality is very out of focus. Not much time taken when trying to capture the moment here</td>', 'The grass is definitely very distracting and not to mention that the image in it''s totality is very out of focus. Not much time taken when trying to capture the moment here', '2015-06-28 12:36:07.000000', NULL, 1),
(7374827, 1154994, 38032, '<td valign="top">WTP? Mystifying.</td>', 'WTP? Mystifying.', '2015-06-28 12:37:33.000000', NULL, 1),
(7374828, 1155447, 180696, '<td valign="top">Lovely array of feathers and complete sharpness and wonderful colours. Very well captured and of course keeping in mind that it is often not easy to capture these birds as they flaunt their tail feathers like this.</td>', 'Lovely array of feathers and complete sharpness and wonderful colours. Very well captured and of course keeping in mind that it is often not easy to capture these birds as they flaunt their tail feathers like this.', '2015-06-28 12:38:03.000000', NULL, 1),
(7374829, 1155946, 180696, '<td valign="top">It is sad to see that this image is dead centred, a more dramatic approach to the angle of view here could''ve made a difference. I also find that there are distracting and messy looking stray feathers on the rest of the image. This doesn''t lend to the appeal</td>', 'It is sad to see that this image is dead centred, a more dramatic approach to the angle of view here could''ve made a difference. I also find that there are distracting and messy looking stray feathers on the rest of the image. This doesn''t lend to the appeal', '2015-06-28 12:40:40.000000', NULL, 1),
(7374830, 1155620, 180696, '<td valign="top">This is a very family type photo for the album, not really well thought out</td>', 'This is a very family type photo for the album, not really well thought out', '2015-06-28 12:41:34.000000', NULL, 1),
(7374832, 1155207, 180696, '<td valign="top">Firstly the vehicle adds absolutely no value to your image at all, then I fail to find the feathers at first glance. An abstract DOF could''ve helped you out here. The road, the buildings in the background doesn''t lend to the main aim at all and looks uninteresting and messy</td>', 'Firstly the vehicle adds absolutely no value to your image at all, then I fail to find the feathers at first glance. An abstract DOF could''ve helped you out here. The road, the buildings in the background doesn''t lend to the main aim at all and looks uninteresting and messy', '2015-06-28 12:44:05.000000', NULL, 1),
(7374833, 1155693, 180696, '<td valign="top">I get the idea, but looking at the working of the image, it is washed out with the light overlay, it seems that you''ve tried to "brighten" up the image in the post processing or something, Doesn''t quite work</td>', 'I get the idea, but looking at the working of the image, it is washed out with the light overlay, it seems that you''ve tried to "brighten" up the image in the post processing or something, Doesn''t quite work', '2015-06-28 12:46:04.000000', NULL, 1),
(7374835, 1155739, 180696, '<td valign="top">A well captured shot, would have left a little more space in front of the bird to "fly" into so to say...</td>', 'A well captured shot, would have left a little more space in front of the bird to "fly" into so to say...', '2015-06-28 12:47:05.000000', NULL, 1),
(7374836, 1155349, 180696, '<td valign="top">Your image is grainy and noisy. The colours are washed out and the DOF isn''t quite right. The background is a tad messy</td>', 'Your image is grainy and noisy. The colours are washed out and the DOF isn''t quite right. The background is a tad messy', '2015-06-28 12:48:35.000000', NULL, 1),
(7374839, 1155536, 180696, '<td valign="top">Nice idea, just not sure whether it looks good against the background, it''s a little distracting to see the two dark spots at the top of your image</td>', 'Nice idea, just not sure whether it looks good against the background, it''s a little distracting to see the two dark spots at the top of your image', '2015-06-28 12:50:36.000000', NULL, 1),
(7374840, 1155192, 180696, '<td valign="top">Good, colourful and sharp image</td>', 'Good, colourful and sharp image', '2015-06-28 12:51:07.000000', NULL, 1),
(7374841, 1155955, 180696, '<td valign="top">I must say that it is a great moment that was caught, I''m not quite sure whether there are any feathers in the image to depict the theme correctly</td>', 'I must say that it is a great moment that was caught, I''m not quite sure whether there are any feathers in the image to depict the theme correctly', '2015-06-28 12:52:19.000000', NULL, 1),
(7374842, 1155740, 180696, '<td valign="top">It''s a lovely bird, who wouldn''t love them. I do however find that you could have improved on better depth of field. The background is distracting and I also find that the image seems to have too much noise, not sure whether it happened during the post processing?</td>', 'It''s a lovely bird, who wouldn''t love them. I do however find that you could have improved on better depth of field. The background is distracting and I also find that the image seems to have too much noise, not sure whether it happened during the post processing?', '2015-06-28 12:54:29.000000', NULL, 1),
(7374844, 1154691, 180696, '<td valign="top">This is what I call great depth of field, causing the bird to stand out as much as it does! Beautiful colours sharp where it needs to be. Good photo</td>', 'This is what I call great depth of field, causing the bird to stand out as much as it does! Beautiful colours sharp where it needs to be. Good photo', '2015-06-28 12:56:00.000000', NULL, 1),
(7374846, 1155163, 180696, '<td valign="top">I find your image to unbalanced and tightly cropped not to mention extremely full of noise. Check your white balance too.</td>', 'I find your image to unbalanced and tightly cropped not to mention extremely full of noise. Check your white balance too.', '2015-06-28 12:57:32.000000', NULL, 1),
(7374848, 1155565, 180696, '<td valign="top">Ask yourself, will this image work if it were to be printed on a canvas and hung on your wall? I personally feel that it will be lost and not much detail will be shown. There is just too much white. I get your idea of keeping it soft, but a little hue to the background would have helped your subject matter stand out just a little more without losing your idea you have here. The leading line created with the feather is good though, I must say.</td>', 'Ask yourself, will this image work if it were to be printed on a canvas and hung on your wall? I personally feel that it will be lost and not much detail will be shown. There is just too much white. I get your idea of keeping it soft, but a little hue to the background would have helped your subject matter stand out just a little more without losing your idea you have here. The leading line created with the feather is good though, I must say.', '2015-06-28 13:00:54.000000', NULL, 1),
(7374857, 1154980, 180696, '<td valign="top">Your image seems to have a bit too much "noise" Is this from the post processing?</td>', 'Your image seems to have a bit too much "noise" Is this from the post processing?', '2015-06-28 13:15:31.000000', NULL, 1),
(7374858, 1154902, 180696, '<td valign="top">It''s a beautiful portrayal of the theme and very well thought out. Well done!</td>', 'It''s a beautiful portrayal of the theme and very well thought out. Well done!', '2015-06-28 13:16:34.000000', NULL, 1),
